import React, { useEffect, useMemo, useRef, useState } from 'react'
import { createRoot } from 'react-dom/client'
import { createPortal } from 'react-dom'
import { Activity, AlertTriangle, ArrowDownRight, ArrowUpRight, Bot, CalendarDays, Check, ChevronDown, CircleHelp, Clock3, Copy, Cpu, FileText, Gauge, KeyRound, LayoutDashboard, LoaderCircle, LockKeyhole, MoreHorizontal, PanelLeftClose, PanelLeftOpen, Plus, Radio, RefreshCw, Search, Settings2, ShieldCheck, Sparkles, Trash2, X, Zap } from 'lucide-react'
import { Badge } from './components/ui/badge'
import { Button } from './components/ui/button'
import './style.css'
import DeploymentDialog from './DeploymentDialog'
import ProviderPresets from './ProviderPresets'
import TokenUsage from './TokenUsage'
import RequestTrend from './RequestTrend'

const formatDuration = ms => typeof ms === 'number' && Number.isFinite(ms) && ms >= 0 ? `${(ms/1000).toFixed(2)} s` : '—'
const compactCount = value => { const n=Number(value)||0; if(n>=1e6)return `${(n/1e6).toFixed(2)} M`; if(n>=1e3)return `${(n/1e3).toFixed(2)} K`; return String(n) }

const API = window.location.hostname === 'tauri.localhost' || window.location.protocol === 'tauri:' ? 'http://127.0.0.1:8787/api' : '/api'
async function api(path, options = {}) {
  const res = await fetch(API + path, { headers: { 'Content-Type': 'application/json', ...(options.headers || {}) }, ...options })
  if (!res.ok) { const body = await res.json().catch(() => ({})); throw new Error(body.detail?.error?.message || body.detail || body.error || `请求失败 (${res.status})`) }
  return res.json()
}
const initials = (name='') => name.slice(0, 1).toUpperCase()
const providerColor = p => p === 'anthropic' ? 'violet' : 'green'
const localInputTime = ms => { const d=new Date(ms); return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}T${String(d.getHours()).padStart(2,'0')}:${String(d.getMinutes()).padStart(2,'0')}` }
const dayStart = d => new Date(d.getFullYear(),d.getMonth(),d.getDate())
const sameDay = (a,b) => a.getFullYear()===b.getFullYear()&&a.getMonth()===b.getMonth()&&a.getDate()===b.getDate()
const todayRange = () => { const now=new Date(); return [dayStart(now).getTime(),now.getTime()] }
function DateRangePicker({start,end,onChange}) {
  const anchor=useRef(null)
  const [position,setPosition]=useState({left:8,top:8})
  const [open,setOpen]=useState(false), [month,setMonth]=useState(dayStart(new Date(start)))
  useEffect(()=>{
    if(!open)return
    const place=()=>{const rect=anchor.current.getBoundingClientRect();const width=Math.min(792,window.innerWidth-16);setPosition({left:Math.max(8,Math.min(rect.right-width,window.innerWidth-width-8)),top:Math.max(8,Math.min(rect.bottom+7,window.innerHeight-460))})}
    const close=e=>{if(e.key==='Escape')setOpen(false)}
    place();window.addEventListener('resize',place);window.addEventListener('scroll',place,true);window.addEventListener('keydown',close)
    return ()=>{window.removeEventListener('resize',place);window.removeEventListener('scroll',place,true);window.removeEventListener('keydown',close)}
  },[open])
  const moveMonth=n=>setMonth(d=>new Date(d.getFullYear(),d.getMonth()+n,1))
  const emitRange=(s,e,adjust='end')=>{const now=Date.now(),hour=3600000,max=7*86400000;s=Math.max(0,Math.min(s,now));e=Math.max(0,Math.min(e,now));if(e-s<hour){if(adjust==='start')s=Math.max(0,e-hour);else e=Math.min(now,s+hour);if(e-s<hour)s=Math.max(0,e-hour)}if(e-s>max){if(adjust==='start')s=e-max;else e=s+max}onChange(s,e)}
  const daysFor=offset=>{const first=new Date(month.getFullYear(),month.getMonth()+offset,1), begin=new Date(first);begin.setDate(1-first.getDay());return Array.from({length:42},(_,i)=>{const d=new Date(begin);d.setDate(begin.getDate()+i);return d})}
  const choose=d=>{const ts=dayStart(d).getTime(),a=dayStart(new Date(start)).getTime(),b=dayStart(new Date(end)).getTime();if(sameDay(new Date(a),new Date(b))||ts<a){emitRange(ts,Math.min(end,ts+7*86400000),'end')}else{const time=new Date(end);const e=new Date(ts);e.setHours(time.getHours(),time.getMinutes(),0,0);emitRange(start,e.getTime(),'end')}}
  const preset=hours=>{const e=Date.now(),s=e-hours*3600000;emitRange(s,e);setMonth(dayStart(new Date(s)));setOpen(false)}
  const todayPreset=()=>{const end=Date.now(),start=dayStart(new Date(end)).getTime();onChange(start,end);setMonth(dayStart(new Date(end)));setOpen(false)}
  const cal=(offset)=>{const title=new Date(month.getFullYear(),month.getMonth()+offset,1);return <section className="range-calendar" key={offset}><h4>{title.toLocaleDateString('en-US',{month:'long',year:'numeric'})}</h4><div className="range-week">{'SMTWTFS'.split('').map((x,i)=><span key={i}>{x}</span>)}</div><div className="range-days">{daysFor(offset).map((d,i)=>{const ts=dayStart(d).getTime(), selected=ts>=dayStart(new Date(start)).getTime()&&ts<=dayStart(new Date(end)).getTime();return <button key={i} disabled={d>Date.now()} className={`${d.getMonth()!==title.getMonth()?'outside ':''}${selected?'in-range ':''}${sameDay(d,new Date(start))||sameDay(d,new Date(end))?'range-edge':''}`} onClick={()=>choose(d)}>{d.getDate()}</button>})}</div></section>}
  return <div className="date-range-picker" ref={anchor}><button className="date-range-trigger" onClick={()=>setOpen(v=>!v)}><CalendarDays size={15}/><span>{new Date(start).toLocaleDateString('zh-CN',{month:'2-digit',day:'2-digit'})} {new Date(start).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit',hour12:false})} — {new Date(end).toLocaleDateString('zh-CN',{month:'2-digit',day:'2-digit'})} {new Date(end).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit',hour12:false})}</span><ChevronDown size={13}/></button>{open&&createPortal(<><button className="range-dismiss" onClick={()=>setOpen(false)} aria-label="关闭日期选择"/><div className="range-popover" style={position} role="dialog" aria-label="选择日期范围"><div className="range-calendars"><div className="range-month-nav"><button onClick={()=>moveMonth(-1)}>‹</button><button onClick={()=>moveMonth(1)}>›</button></div>{cal(0)}{cal(1)}<div className="range-time-row"><label>开始时间<input type="time" value={localInputTime(start).slice(11)} onChange={e=>{const d=new Date(start),[h,m]=e.target.value.split(':');d.setHours(+h,+m);emitRange(d.getTime(),end,'start')}}/></label><label>结束时间<input type="time" value={localInputTime(end).slice(11)} onChange={e=>{const d=new Date(end),[h,m]=e.target.value.split(':');d.setHours(+h,+m);emitRange(start,d.getTime(),'end')}}/></label></div></div><aside className="range-presets"><button onClick={todayPreset}>当天区间</button>{[[1,'最近 1 小时'],[6,'最近 6 小时'],[24,'最近 24 小时'],[168,'最近 7 天']].map(([h,label])=><button key={h} onClick={()=>preset(h)}>{label}</button>)}<div className="range-zone">范围限制 <b>最短 1 小时 · 最长 7 天</b></div></aside></div></>,document.body)}</div>
}

function StatCard({ icon: Icon, label, value, detail, trend, color='blue' }) { return <div className="stat-card"><div className={`stat-icon ${color}`}><Icon size={18}/></div><div className="stat-label">{label}</div><div className="stat-value">{value}</div><div className="stat-detail">{trend && <span className="trend"><ArrowUpRight size={13}/>{trend}</span>}{detail}</div></div> }

const emptyForm = { name:'', alias:'', provider:'openai', base_url:'https://api.openai.com', upstream_model:'', api_keys:[], enabled:true, thinking_mode:false, base_weight:1, auto_weight:1, weight_locked:false, proxy_url:'', use_system_proxy:true, rpm:0, max_input_tokens:0, max_output_tokens:0, timeout_seconds:90, note:'' }

function App() {
  const [tab, setTab] = useState('overview')
  const [deps, setDeps] = useState([])
  const [summary, setSummary] = useState(null)
  const [events, setEvents] = useState([])
  const [settings, setSettings] = useState(null)
  const [bootstrap, setBootstrap] = useState(null)
  const [query, setQuery] = useState('')
  const [modal, setModal] = useState(false)
  const [editing, setEditing] = useState(null)
  const [form, setForm] = useState(emptyForm)
  const [keyText, setKeyText] = useState('')
  const [testingConnection, setTestingConnection] = useState(false)
  const [fetchingModels, setFetchingModels] = useState(false)
  const [availableModels, setAvailableModels] = useState([])
  const [toast, setToast] = useState('')
  const [busy, setBusy] = useState(false)
  const [showKey, setShowKey] = useState(false)
  const [selectedEvent, setSelectedEvent] = useState(null)
  const [selectedModel, setSelectedModel] = useState(null)
  const [modelDetailTab, setModelDetailTab] = useState('info')
  const [eventDetailTab, setEventDetailTab] = useState('overview')
  const [settingsSubtab, setSettingsSubtab] = useState('general')
  const [logQuery, setLogQuery] = useState('')
  const [logRange, setLogRange] = useState(todayRange)
  const [overviewDrawer, setOverviewDrawer] = useState(null)
  const [logStart, logEnd] = logRange
  const [logPage, setLogPage] = useState(1)
  const [logsLive, setLogsLive] = useState(false)
  const logsLiveRef = useRef(false)
  const logRangeManuallyChanged = useRef(false)
  const [logStatusOpen, setLogStatusOpen] = useState(false)
  const [sidebarCollapsed, setSidebarCollapsed] = useState(false)
  const [serviceMenuOpen, setServiceMenuOpen] = useState(false)
  const serviceMenuRef = useRef(null)
  const [refreshing, setRefreshing] = useState(false)
  const [tuningSettingsOpen, setTuningSettingsOpen] = useState(false)
  const [historyDrawer, setHistoryDrawer] = useState(null)
  const [historyData, setHistoryData] = useState({weights:{items:[],total:0},audits:{items:[],total:0}})
  const [historyLoading, setHistoryLoading] = useState(false)
  const [expandedHistoryId, setExpandedHistoryId] = useState(null)
  const [aiForm, setAiForm] = useState({enabled:false,provider:'openai',base_url:'https://api.openai.com/v1',model:'',api_key:'',key_saved:false})
  const aiLoaded = useRef(false)
  const [ruleForm, setRuleForm] = useState({enabled:true,failure_threshold:3,cooldown_seconds:90,min_auto_factor:0.25,max_auto_factor:1.5})
  const rulesLoaded = useRef(false)

  const refresh = async () => {
    try {
      const [d,s,e,st,b] = await Promise.all([api('/deployments'), api('/summary'), logsLiveRef.current ? Promise.resolve(null) : api('/events?limit=500'), api('/settings'), api('/bootstrap')])
      setDeps(d); setSummary(s); if(e)setEvents(e); setSettings(st); setBootstrap(b)
      if (st.ai && !aiLoaded.current) { setAiForm(old=>({...old,...st.ai,api_key:''})); aiLoaded.current=true }
      if (st.rules && !rulesLoaded.current) { setRuleForm(old=>({...old,...st.rules})); rulesLoaded.current=true }
      return true
    } catch (e) { setToast(e.message); return false }
  }
  const manualRefresh = async () => { setRefreshing(true); const ok=await refresh(); if(ok)setToast('数据已刷新'); setRefreshing(false) }
  const openHistory = async kind => { setHistoryDrawer(kind); setExpandedHistoryId(null); setHistoryLoading(true); try { const data=await api(`/history/${kind}?limit=20&offset=0`); setHistoryData(old=>({...old,[kind]:data})) } catch(e) { if(e.message==='Not Found'||e.message.includes('404')) { const items=kind==='weights'?(settings?.weight_events||[]):(settings?.ai_audits||[]); setHistoryData(old=>({...old,[kind]:{items,total:items.length,limit:items.length,offset:0}})) } else setToast(e.message) } finally { setHistoryLoading(false) } }
  const loadMoreHistory = async () => { if(!historyDrawer)return; const current=historyData[historyDrawer]; setHistoryLoading(true); try { const data=await api(`/history/${historyDrawer}?limit=20&offset=${current.items.length}`); setHistoryData(old=>({...old,[historyDrawer]:{...data,items:[...old[historyDrawer].items,...data.items]}})) } catch(e) { setToast(e.message) } finally { setHistoryLoading(false) } }
  useEffect(() => { refresh(); const timer=setInterval(refresh, 12000); return ()=>clearInterval(timer) }, [])
  useEffect(() => { logsLiveRef.current=logsLive }, [logsLive])
  useEffect(() => {
    const now = Date.now()
    const recentHours = logEnd >= now - 60_000 && logStart < now && now - logStart <= 24 * 60 * 60 * 1000
    if (!logsLive || tab !== 'logs' || !recentHours || document.hidden) return
    const source = new EventSource(`${API}/events/stream?start=${Math.floor(logStart)}&end=${Math.floor(logEnd)}`)
    let busy = false
    source.addEventListener('new', async () => {
      if (busy) return
      busy = true
      try {
        setEvents(await api('/events?limit=500'))
        setLogRange(([start]) => [start, Date.now()])
      } catch {} finally { busy = false }
    })
    return () => source.close()
  }, [logsLive,tab,logStart,logEnd])
  useEffect(() => {
    const refreshRange = () => { if (!logRangeManuallyChanged.current) setLogRange(todayRange()) }
    document.addEventListener('visibilitychange', refreshRange)
    return () => document.removeEventListener('visibilitychange', refreshRange)
  }, [])
  useEffect(() => { const timer=setInterval(()=>{if(logRangeManuallyChanged.current)return;const [start,end]=todayRange();setLogRange([start,end])},60000);return()=>clearInterval(timer) }, [])
  useEffect(() => { if (toast) { const id=setTimeout(()=>setToast(''),3200); return ()=>clearTimeout(id) } }, [toast])
  useEffect(() => {
    if (!serviceMenuOpen) return
    const closeOutside = event => { if (serviceMenuRef.current && !serviceMenuRef.current.contains(event.target)) setServiceMenuOpen(false) }
    const closeOnEscape = event => { if (event.key === 'Escape') setServiceMenuOpen(false) }
    document.addEventListener('pointerdown', closeOutside)
    document.addEventListener('keydown', closeOnEscape)
    return () => { document.removeEventListener('pointerdown', closeOutside); document.removeEventListener('keydown', closeOnEscape) }
  }, [serviceMenuOpen])

  const aliases = useMemo(() => [...new Set(deps.map(d=>d.alias))], [deps])
  const filtered = deps.filter(d => `${d.name} ${d.alias} ${d.provider} ${d.upstream_model}`.toLowerCase().includes(query.toLowerCase()))
  const fmtTime = value => value ? new Date(value).toLocaleString('zh-CN',{hour12:false}) : '—'
  const logFiltered = useMemo(() => {
    const q = logQuery.trim().toLowerCase()
    return events.filter(ev => {const t=new Date(ev.created_at).getTime(); return t>=logStart&&t<=logEnd && (!q || `${ev.request_id} ${ev.alias} ${ev.deployment_name} ${ev.supplier_name||''} ${ev.error_message} ${ev.error_kind}`.toLowerCase().includes(q))})
  }, [events, logQuery, logStart, logEnd])
  const logStats = useMemo(() => {
    const ok = logFiltered.filter(e => e.status === 'success').length
    const latencies = logFiltered.map(e => Number(e.latency_ms)).filter(n => Number.isFinite(n) && n > 0).sort((a,b)=>a-b)
    return {total:logFiltered.length, failed:logFiltered.length-ok, rate:logFiltered.length ? ok/logFiltered.length*100 : 0, avg:latencies.length ? Math.round(latencies.reduce((a,b)=>a+b,0)/latencies.length) : 0, p95:latencies.length ? latencies[Math.ceil(latencies.length*.95)-1] : 0, tokens:logFiltered.reduce((sum,e)=>sum+(Number(e.total_tokens)||0),0), tokenEvents:logFiltered.filter(e=>e.total_tokens!=null).length}
  }, [logFiltered])

  const logPageSize=25
  const logPageCount=Math.max(1,Math.ceil(logFiltered.length/logPageSize))
  const logPageRows=logFiltered.slice((logPage-1)*logPageSize,logPage*logPageSize)
  const openCreate = () => { setEditing(null); setForm(emptyForm); setKeyText(''); setAvailableModels([]); setModal(true) }
  const openEdit = dep => { setEditing(dep); setForm({...dep, api_keys:[]}); setKeyText(''); setAvailableModels([]); setModal(true) }
  const saveDeployment = async e => {
    e.preventDefault(); setBusy(true)
    try {
      const payload={...form, name:form.name.trim()||form.upstream_model.trim(), alias:form.alias.trim()||form.upstream_model.trim(), upstream_model:form.upstream_model.trim(), base_url:form.base_url.trim().replace(/\/+$/,''), api_keys:keyText.split(/\r?\n/).map(x=>x.trim()).filter(Boolean)}
      if (editing && !keyText.trim()) payload.api_keys = [] // API merge preserves existing credentials when no new keys supplied.
      await api(editing ? `/deployments/${editing.id}` : '/deployments', { method:editing?'PUT':'POST', body:JSON.stringify(payload) })
      setModal(false); setToast(editing?'模型配置已更新':'模型部署已添加'); await refresh()
    } catch (err) { setToast(err.message) } finally { setBusy(false) }
  }
  const testDeployment = async () => {
    const token = keyText.split(/\r?\n/).map(x=>x.trim()).find(Boolean) || (editing ? '__saved__' : '')
    if (!form.base_url || !form.upstream_model || !token) { setToast('请先填写 API Base URL、模型 ID 和至少一个 API Token'); return }
    setTestingConnection(true)
    try {
      const result = await api('/deployments/test-connection', {method:'POST', body:JSON.stringify({provider:form.provider,base_url:form.base_url,api_key:token,upstream_model:form.upstream_model,proxy_url:form.proxy_url,use_system_proxy:form.use_system_proxy,timeout_seconds:form.timeout_seconds, deployment_id:editing?.id})})
      setToast(result.message || '连接成功')
    } catch (err) { setToast(err.message) } finally { setTestingConnection(false) }
  }
  const fetchModels = async () => {
    const token = keyText.split(/\r?\n/).map(x=>x.trim()).find(Boolean) || (editing ? '__saved__' : '')
    if (!form.base_url || !token) { setToast('请先填写 API Base URL 和至少一个 API Token'); return }
    setFetchingModels(true)
    try {
      const result = await api('/deployments/test-connection', {method:'POST', body:JSON.stringify({provider:form.provider,base_url:form.base_url,api_key:token,proxy_url:form.proxy_url,use_system_proxy:form.use_system_proxy,timeout_seconds:form.timeout_seconds,models_url:form.models_url,deployment_id:editing?.id})})
      setAvailableModels(result.models || [])
      if (result.models?.length) setToast(`已获取 ${result.models.length} 个模型，请在模型 ID 输入框选择`)
      else setToast(result.message || '上游没有返回可用模型，请手动填写模型 ID')
    } catch (err) { setToast(err.message) } finally { setFetchingModels(false) }
  }
  const deleteDeployment = async dep => { if (!confirm(`确定删除“${dep.name}”吗？`)) return; try { await api(`/deployments/${dep.id}`,{method:'DELETE'}); setToast('已删除模型部署'); refresh() } catch(e){setToast(e.message)} }
  const toggleDeployment = async dep => { const enabled=!dep.enabled;try{const payload={name:dep.name,alias:dep.alias,provider:dep.provider,supplier_id:dep.supplier_id||'',supplier_name:dep.supplier_name||'',base_url:dep.base_url,full_url:dep.full_url,thinking_mode:dep.thinking_mode,upstream_model:dep.upstream_model,api_keys:[],enabled,base_weight:dep.base_weight,auto_weight:dep.auto_weight,weight_locked:dep.weight_locked,proxy_url:dep.proxy_url||'',use_system_proxy:dep.use_system_proxy,rpm:dep.rpm||0,max_input_tokens:dep.max_input_tokens||0,max_output_tokens:dep.max_output_tokens||0,timeout_seconds:dep.timeout_seconds||90,note:dep.note||''};const updated=await api(`/deployments/${dep.id}`,{method:'PUT',body:JSON.stringify(payload)});setSelectedModel(updated);setDeps(old=>old.map(item=>item.id===updated.id?updated:item));setToast(enabled?'模型已启用':'模型已停用')}catch(e){setToast(e.message)} }
  const analyze = async () => { setBusy(true); try { const result=await api('/ai/analyze',{method:'POST',body:JSON.stringify({})}); await refresh(); setTab('tuning'); if(result.status==='failed'){setToast(`AI 分析失败：${result.report?.analysis_error||'上游服务调用失败'}；本地指标快照已保存`)}else{setToast(result.status==='complete'&&aiForm.enabled?'AI 综合分析已完成':'已生成指标分析快照')} } catch(e){setToast(e.message)} finally{setBusy(false)} }
  const tune = async () => { setBusy(true); try { const result=await api('/ai/tune',{method:'POST',body:JSON.stringify({})}); await refresh(); setToast(result.status==='no_change'?'AI 建议无需调整权重':`已应用 ${result.changes.length} 项 AI 权重建议`) } catch(e){setToast(e.message)} finally{setBusy(false)} }
  const saveAi = async e => { e.preventDefault(); setBusy(true); try { const value=await api('/settings/ai',{method:'PUT',body:JSON.stringify(aiForm)}); setAiForm(old=>({...old,...value,api_key:''})); await refresh(); setToast('AI 分析配置已保存') }catch(err){setToast(err.message)}finally{setBusy(false)} }
  const saveRules = async ev => { ev.preventDefault(); try { const result=await api('/settings/rules',{method:'PUT',body:JSON.stringify(ruleForm)}); setRuleForm(result); setSettings({...settings,rules:result}); setToast('路由规则已保存') }catch(e){setToast(e.message)} }
  const saveProviderPresets = async presets => { const result=await api('/settings/provider-presets',{method:'PUT',body:JSON.stringify({presets})});setSettings(old=>({...old,provider_presets:result.presets}));return result }
  const toggleAi = async enabled => { const previous=aiForm.enabled; const next={...aiForm,enabled}; setAiForm(next); setBusy(true); try { const saved=await api('/settings/ai',{method:'PUT',body:JSON.stringify(next)}); setAiForm(old=>({...old,...saved,api_key:''})); setToast(enabled?'AI 分析已启用':'AI 分析已停用') }catch(e){setAiForm(old=>({...old,enabled:previous}));setToast(e.message)}finally{setBusy(false)} }
  const toggleRules = async enabled => { const previous=ruleForm.enabled; const next={...ruleForm,enabled}; setRuleForm(next); try { const saved=await api('/settings/rules',{method:'PUT',body:JSON.stringify(next)}); setRuleForm(saved); setSettings(old=>old?({...old,rules:saved}):old); setToast(enabled?'规则路由已启用':'规则路由已停用') }catch(e){setRuleForm(old=>({...old,enabled:previous}));setToast(e.message)} }
  const copy = async value => { await navigator.clipboard.writeText(value); setToast('已复制到剪贴板') }

  return <div className={`shell ${sidebarCollapsed?'sidebar-collapsed':''}`}>
    <aside className="sidebar">
      <div className="brand"><div className="brand-mark"><Radio size={19}/></div><div className="brand-copy"><b>模型路由器</b><small>本地 AI 服务</small></div></div>
      <div className="side-caption">工作区</div>
      <nav>
        <button title="概览" className={tab==='overview'?'active':''} onClick={()=>setTab('overview')}><LayoutDashboard size={17}/><span className="nav-label">概览</span></button>
        <button title="模型路由" className={tab==='models'?'active':''} onClick={()=>setTab('models')}><Bot size={17}/><span className="nav-label">模型路由</span><span className="nav-count">{deps.length}</span></button>
        <button title="请求日志" className={tab==='logs'?'active':''} onClick={()=>setTab('logs')}><FileText size={17}/><span className="nav-label">请求日志</span></button>
        <button title="自动调优" className={tab==='tuning'?'active':''} onClick={()=>setTab('tuning')}><Sparkles size={17}/><span className="nav-label">自动调优</span></button>
      </nav>
      <div className="side-caption settings-caption">偏好设置</div>
      <nav><button title="系统设置" className={tab==='settings'?'active':''} onClick={()=>setTab('settings')}><Settings2 size={17}/><span className="nav-label">系统设置</span></button></nav>
      <div className="side-spacer"/>
      <div className="sidebar-status" ref={serviceMenuRef}><span className="status-dot"/><div className="service-copy"><b>本地服务运行中</b><small>127.0.0.1:8787</small></div><button className="service-menu-trigger" title="服务选项" onClick={()=>setServiceMenuOpen(v=>!v)}><MoreHorizontal size={17}/></button>{serviceMenuOpen&&<div className="service-menu"><button onClick={()=>{copy(bootstrap?.base_url||'http://127.0.0.1:8787/v1');setServiceMenuOpen(false)}}><Copy size={14}/>复制 API 地址</button><button onClick={()=>{setTab('settings');setServiceMenuOpen(false)}}><Settings2 size={14}/>服务与数据设置</button><small>关闭窗口后，服务会留在系统托盘运行</small></div>}</div>
      <div className="profile"><div className="avatar"><Cpu size={14}/></div><div className="profile-copy"><b>个人自用</b><small>版本 0.1.0</small></div></div>
    </aside>
    <main className="main">
      <header className="topbar"><div className="top-leading"><button className="icon-button sidebar-toggle" title={sidebarCollapsed?'展开侧边栏':'收起侧边栏'} onClick={()=>setSidebarCollapsed(v=>!v)}>{sidebarCollapsed?<PanelLeftOpen size={17}/>:<PanelLeftClose size={17}/>}</button><div className="crumb">本地模型路由器 <span>/</span> <b>{({overview:'概览',models:'模型路由',logs:'请求日志',tuning:'自动调优',settings:'系统设置'})[tab]}</b></div></div><div className="top-actions"><div className="service-pill"><i/>服务正常</div><button className="icon-button" title="立即刷新数据" onClick={manualRefresh} disabled={refreshing}>{refreshing?<RefreshCw className="spin" size={16}/>:<RefreshCw size={16}/>}</button><div className="top-avatar">L</div></div></header>
      <div className="content">
        {tab==='overview' && <>
          <div className="page-heading"><div><div className="eyebrow">USAGE ANALYTICS</div><h1>服务概览</h1><p>按请求日志的时间区间统计供应商用量、实际响应延迟与模型使用情况</p></div><div className="overview-actions"><DateRangePicker start={logStart} end={logEnd} onChange={(s,e)=>{logRangeManuallyChanged.current=true;setLogRange([s,e]);setLogPage(1)}}/></div></div>
          {(() => {
            const recent=events.filter(e=>{const t=new Date(e.created_at).getTime();return t>=logStart&&t<=logEnd})
            const aggregate=(key,fallback)=>{const map=new Map();for(const e of recent){const name=e[key]||e[fallback]||'未知';const r=map.get(name)||{name,count:0,tokens:0,latency:0,latencyCount:0};r.count++;r.tokens+=Number(e.total_tokens)||0;const ms=Number(e.latency_ms);if(Number.isFinite(ms)&&ms>=0){r.latency+=ms;r.latencyCount++}map.set(name,r)}return [...map.values()]}
            const providers=aggregate('supplier_name','deployment_name').sort((a,b)=>b.tokens-a.tokens),models=aggregate('alias','deployment_name').sort((a,b)=>b.count-a.count)
            const tokens=providers.reduce((n,x)=>n+x.tokens,0),latencyCount=providers.reduce((n,x)=>n+x.latencyCount,0),latency=latencyCount?providers.reduce((n,x)=>n+x.latency,0)/latencyCount:0
            const chart=(title,desc,rows,field,max,fmt,total)=> <section className="panel overview-chart" role="button" tabIndex={0} onClick={()=>setOverviewDrawer({title,total,rows:[...rows].sort((a,b)=>b[field]-a[field]),field,format:fmt})} onKeyDown={e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();setOverviewDrawer({title,total,rows:[...rows].sort((a,b)=>b[field]-a[field]),field,format:fmt})}}} aria-label={`${title}，点击查看全部记录`}><header><div><h2>{title}</h2><p>{desc}</p></div><b title={total}>{total}</b></header>{rows.length?<div className="overview-bars">{[...rows].sort((a,b)=>b[field]-a[field]).slice(0,6).map(r=><div className="overview-bar-row" key={r.name}><span title={r.name}>{r.name}</span><div><i style={{width:`${Math.max(2,r[field]/max*100)}%`}}/></div><b title={fmt(r[field])}>{fmt(r[field])}</b></div>)}</div>:<div className="overview-empty">当前时间区间暂无可展示的请求数据</div>}</section>
            const tokenRows=providers.map(x=>({...x,value:x.tokens})), latencyRows=providers.filter(x=>x.latencyCount).map(x=>({...x,value:x.latency/x.latencyCount})).sort((a,b)=>b.value-a.value), modelRows=models.map(x=>({...x,value:x.count})), modelTokenRows=models.map(x=>({...x,value:x.tokens})).sort((a,b)=>b.value-a.value)
            const successCount=recent.filter(e=>e.status==='success').length, successRate=recent.length?successCount/recent.length*100:0
            return <><div className="overview-kpis"><div><span className="overview-kpi-label">可用部署 <span className="overview-help" tabIndex="0" data-tooltip="当前已启用、可参与请求路由的模型部署数量。" aria-label="当前已启用、可参与请求路由的模型部署数量。"><CircleHelp size={13}/></span></span><b>{summary?.deployments?.enabled||0}</b><small>共 {summary?.deployments?.total||0} 个部署</small></div><div><span className="overview-kpi-label">请求成功率 <span className="overview-help" tabIndex="0" data-tooltip="当前选择的时间区间内，成功请求数占全部已记录请求数的比例。" aria-label="当前选择的时间区间内，成功请求数占全部已记录请求数的比例。"><CircleHelp size={13}/></span></span><b>{successRate.toFixed(1)}%</b><small>成功 {successCount} / 共 {recent.length} 次请求</small></div><div><span className="overview-kpi-label">冷却中的部署 <span className="overview-help" tabIndex="0" data-tooltip="因近期请求失败而暂时停止路由、等待自动恢复的部署数量。" aria-label="因近期请求失败而暂时停止路由、等待自动恢复的部署数量。"><CircleHelp size={13}/></span></span><b>{summary?.cooldowns||0}</b><small>自动恢复中</small></div><div><span className="overview-kpi-label">逻辑模型 <span className="overview-help" tabIndex="0" data-tooltip="已配置的不同逻辑模型别名数量，客户端可通过这些别名发起请求。" aria-label="已配置的不同逻辑模型别名数量，客户端可通过这些别名发起请求。"><CircleHelp size={13}/></span></span><b>{aliases.length}</b><small>统一 API 别名</small></div></div><div className="overview-grid">
              {chart('服务商的令牌使用情况','按供应商汇总 Token',tokenRows,'value',Math.max(1,...tokenRows.map(x=>x.value)),n=>compactCount(n),`${compactCount(tokens)} tokens`)}
              {chart('模型 Token 使用情况','按逻辑模型统计 Token 消费量',modelTokenRows,'value',Math.max(1,...modelTokenRows.map(x=>x.value)),n=>compactCount(n),`${compactCount(modelTokenRows.reduce((n,x)=>n+x.value,0))} tokens`)}
              {chart('模型的使用情况','按逻辑模型统计请求次数',modelRows,'value',Math.max(1,...modelRows.map(x=>x.value)),n=>`${n} 次`,`${recent.length} 次请求`)}
              {chart('服务商的实际延迟情况','按请求记录计算平均端到端延迟',latencyRows,'value',Math.max(1,...latencyRows.map(x=>x.value)),n=>`${(n/1000).toFixed(2)} 秒`,latency?`${(latency/1000).toFixed(2)} 秒`:'—')}
            </div><div className="overview-footnote">统计范围与请求日志共用时间区间；延迟来自实际请求记录，Token 仅计入上游返回用量的请求。</div></>
          })()}
          {overviewDrawer&&<div className="overview-drawer-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)setOverviewDrawer(null)}}><aside className="overview-drawer" role="dialog" aria-modal="true" aria-label={overviewDrawer.title}><header><div><small>统计明细</small><h2>{overviewDrawer.title}</h2><p>当前时间区间 · {overviewDrawer.rows.length} 条记录</p></div><button className="icon-button" onClick={()=>setOverviewDrawer(null)} aria-label="关闭">×</button></header><div className="overview-drawer-total">合计 <b>{overviewDrawer.total}</b></div><div className="overview-drawer-list">{overviewDrawer.rows.length?overviewDrawer.rows.map((r,i)=><div className="overview-drawer-row" key={r.name}><span className="overview-drawer-rank">{i+1}</span><span className="overview-drawer-name" title={r.name}>{r.name}</span><b title={Number(r[overviewDrawer.field]).toLocaleString()}>{overviewDrawer.format(r[overviewDrawer.field])}</b></div>):<div className="overview-empty">当前时间区间暂无记录</div>}</div></aside></div>}
        </>}        {tab==='models' && <><div className="page-heading"><div><div className="eyebrow">CONFIGURATION</div><h1>模型路由</h1><p>管理供应商部署、上游凭据和路由权重。</p></div><Button variant="primary" onClick={openCreate}><Plus size={16}/>添加模型</Button></div><div className="toolbar"><div className="searchbox"><Search size={16}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="搜索模型、供应商或别名..."/></div><button className="button secondary" onClick={refresh}><RefreshCw size={15}/>刷新</button><button className="button secondary" onClick={()=>setTab('tuning')}><Sparkles size={15}/>调优规则</button></div><div className="panel full-table"><div className="table-wrap"><table><thead><tr><th>模型部署</th><th>逻辑模型</th><th>供应商</th><th>状态</th><th>生效权重</th><th>Token</th><th>RPM</th><th>代理</th><th></th></tr></thead><tbody>{filtered.map(d=><ModelRow key={d.id} dep={d} expanded onSelect={()=>{setSelectedModel(d);setModelDetailTab('info')}} onEdit={()=>openEdit(d)} onDelete={()=>deleteDeployment(d)}/>)}{!filtered.length&&<tr><td colSpan="9"><Empty title={deps.length?'没有匹配项':'开始配置你的模型'} body={deps.length?'试试其他搜索词。':'添加供应商、模型 ID 与 API Token。'} action={openCreate}/></td></tr>}</tbody></table></div><div className="panel-footer"><span>{filtered.length} 个部署 · {aliases.length} 个逻辑模型</span><span className="muted">每 12 秒自动刷新</span></div></div></>}
        {tab==='logs' && <><div className="page-heading"><div><div className="eyebrow">OBSERVABILITY</div><h1>请求日志</h1><p>从请求趋势、失败类型、延迟和路由尝试中定位问题。</p></div><button className="button secondary" onClick={()=>setLogStatusOpen(true)}><Activity size={15}/>查看状态</button></div>
          <div className="logs-toolbar"><div className="logs-search"><Search size={16}/><input value={logQuery} onChange={e=>{setLogQuery(e.target.value);setLogPage(1)}} placeholder="搜索请求 ID、模型、供应商、部署或错误"/><button className={logsLive?'live-active':''} onClick={()=>setLogsLive(v=>!v)}><Radio size={14}/>{logsLive?'实时刷新中':'实时刷新'}</button></div><DateRangePicker start={logStart} end={logEnd} onChange={(s,e)=>{logRangeManuallyChanged.current=true;setLogRange([s,e]);setLogPage(1)}}/></div>
          <RequestTrend events={logFiltered} start={logStart} end={logEnd}/>
          <div className="panel logs-panel"><div className="logs-head"><div><b>请求事件</b><small>显示 {logPageRows.length} / {logFiltered.length} 条 · 已加载最近 {events.length} 条 · 正文不保存</small></div><Badge tone="green" dot>隐私保护已启用</Badge></div><div className="table-wrap"><table><thead><tr><th>时间</th><th>协议</th><th>逻辑模型</th><th>部署</th><th>供应商</th><th>耗时</th><th>Token 用量</th><th>结果 / 状态码</th></tr></thead><tbody>{logPageRows.map(ev=><tr key={ev.id} onClick={()=>{setEventDetailTab('overview');setSelectedEvent(ev)}} className="clickable-row"><td className="mono subtle">{fmtTime(ev.created_at)}</td><td><Badge>{ev.protocol==='anthropic'?'Anthropic':'OpenAI'}</Badge></td><td><code>{ev.alias||'—'}</code></td><td>{ev.deployment_name||'—'}</td><td title={ev.supplier_source==='current_deployment'?'根据当前部署推断，历史记录未保存供应商快照':ev.supplier_name||'未匹配到供应商'}>{ev.supplier_name||'—'}{ev.supplier_source==='current_deployment'&&<small className="supplier-inferred">推断</small>}</td><td className="mono">{formatDuration(ev.latency_ms)}</td><td><TokenUsage event={ev}/></td><td><Badge tone={ev.status==='success'?'green':'red'} dot>{ev.status==='success'?'成功':`失败 · ${ev.status_code||'—'}`}</Badge></td></tr>)}{!logFiltered.length&&<tr><td colSpan="8"><div className="empty-small">{events.length?'没有符合当前搜索和筛选条件的请求。':'尚无请求。配置完成后，客户端请求会显示在这里。'}</div></td></tr>}</tbody></table></div><div className="panel-footer"><span>{events.length>=100?'当前仅载入最近 100 条请求':'已载入全部请求'} · 点击行查看完整路由尝试</span><div className="log-pagination"><button disabled={logPage<=1} onClick={()=>setLogPage(p=>p-1)}>上一页</button><span>{logPage} / {logPageCount}</span><button disabled={logPage>=logPageCount} onClick={()=>setLogPage(p=>p+1)}>下一页</button></div></div></div></>}
        {tab==='logs' && logStatusOpen&&<div className="drawer-backdrop log-status-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)setLogStatusOpen(false)}}><aside className="tuning-drawer log-status-drawer"><div className="drawer-header"><div><small>REQUEST STATUS</small><h2>请求状态</h2></div><button className="icon-button" title="关闭状态面板" onClick={()=>setLogStatusOpen(false)}><X size={18}/></button></div><div className="log-status-body"><div className="log-status-live"><span className={logsLive?'status-dot':'status-dot status-off'}/><div><b>{logsLive?'实时更新中':'实时刷新已关闭'}</b><small>{logsLive?'新请求写入后自动更新':'开启实时刷新后，新请求会自动显示'}</small></div><button className={`button ${logsLive?'secondary':'primary'} small`} onClick={()=>setLogsLive(v=>!v)}><Radio size={13}/>{logsLive?'停止实时':'开启实时'}</button></div><div className="log-status-grid"><div className="log-stat"><small>请求数</small><b>{logStats.total}</b></div><div className="log-stat"><small>成功率</small><b>{logStats.rate.toFixed(1)}%</b></div><div className="log-stat"><small>Token 消耗</small><b>{logStats.tokenEvents?logStats.tokens.toLocaleString():'—'}</b><span>{logStats.tokenEvents?`${logStats.tokenEvents} 条请求有用量数据`:'等待新请求返回用量'}</span></div><div className="log-stat"><small>平均耗时</small><b>{logStats.avg?`${(logStats.avg/1000).toFixed(2)} s`:'—'}</b></div><div className="log-stat"><small>P95 耗时</small><b>{logStats.p95?`${(logStats.p95/1000).toFixed(2)} s`:'—'}</b></div></div><p className="log-status-note">统计范围跟随请求日志当前筛选条件。历史请求没有保存 Token 用量，因此只计入升级后产生且上游返回 usage 的请求。</p></div></aside></div>}
        {tab==='tuning' && <>
          <div className="page-heading tuning-heading">
            <div><h1>自动调优</h1><p>按真实请求表现调整路由，并保留分析审计记录。</p></div>
            <div className="heading-actions">
              <button className="icon-button tuning-config-button" title="调优配置" onClick={()=>setTuningSettingsOpen(true)}><Settings2 size={17}/></button>
            </div>
          </div>
          <div className="tuning-banner"><div className="tuning-orb"><Sparkles size={18}/></div><div className="tuning-banner-copy"><b>调优策略受约束运行</b><p>只分析脱敏指标；AI 建议仅调整未锁定部署的自动权重，并保留审计记录。</p></div><div className="tuning-banner-actions"><button className="button secondary" disabled={busy} onClick={tune}><Sparkles size={14}/>AI 建议调权</button><button className="button primary" disabled={busy} onClick={analyze}>{busy?<LoaderCircle className="spin" size={15}/>:<Sparkles size={15}/>}生成综合分析</button></div></div>
          <div className="tuning-controls">
            <section className="panel tuning-control-row">
              <div className="tuning-control-copy"><span className="tuning-control-icon ai"><Sparkles size={16}/></span><div><b>AI 分析模型</b><small>{aiForm.model||'尚未配置模型'} · 用于综合分析和权重建议</small></div></div>
              <label className="switch" title="启用或停用 AI 分析"><input type="checkbox" checked={aiForm.enabled} onChange={e=>toggleAi(e.target.checked)} disabled={busy}/><span/></label>
            </section>
            <section className="panel tuning-control-row">
              <div className="tuning-control-copy"><span className="tuning-control-icon rules"><ShieldCheck size={16}/></span><div><b>规则路由</b><small>连续失败冷却与权重平滑调整</small></div></div>
              <label className="switch" title="启用或停用规则路由"><input type="checkbox" checked={ruleForm.enabled} onChange={e=>toggleRules(e.target.checked)}/><span/></label>
            </section>
          </div>
          <div className="section-title-row tuning-section-title"><div><h2>权重变更历史</h2><p>规则与 AI 调整均保留调整前后数值和原因</p></div><button className="text-button history-link" onClick={()=>openHistory('weights')}>查看全部 →</button></div>
          <div className="panel audit-panel">{(settings?.weight_events||[]).slice(0,1).map(w=><div className="audit-row" key={w.id}><div className="audit-icon"><Gauge size={16}/></div><div className="audit-info"><b>{w.name} · {w.source==='ai'?'AI 调整':'规则调权'}</b><small>{fmtTime(w.created_at)} · {w.before_weight.toFixed(2)} → {w.after_weight.toFixed(2)} · {w.reason}</small></div><Badge tone={w.after_weight>=w.before_weight?'green':'amber'}>{w.alias}</Badge></div>)}{!settings?.weight_events?.length&&<div className="empty-small">尚无权重变化。</div>}</div>
          <div className="section-title-row tuning-section-title"><div><h2>分析与建议审计</h2><p>最近生成的分析报告与 AI 调权调用记录</p></div><button className="text-button history-link" onClick={()=>openHistory('audits')}>查看全部 →</button></div>
          <div className="panel audit-panel">{(settings?.ai_audits||[]).slice(0,1).map(a=><div className="audit-row" key={a.id}><div className="audit-icon"><FileText size={16}/></div><div className="audit-info"><b>{a.kind==='tune'?'AI 权重调整':'综合分析报告'}</b><small>{fmtTime(a.created_at)} · {a.kind==='tune'?`${a.changes?.length||0} 项变更`:`样本 ${a.report?.metrics?.sampled_events??a.report?.sampled_events??0} 条请求`}</small></div><Badge tone={a.status==='applied'||a.status==='complete'?'green':a.status==='rejected'||a.status==='failed'?'red':'amber'}>{a.status}</Badge><button className="text-button" onClick={()=>alert(JSON.stringify({report:a.report,changes:a.changes},null,2))}>查看记录</button></div>)}{!settings?.ai_audits?.length&&<div className="empty-small">还没有审计记录。生成综合分析报告后可查看。</div>}</div>
          {tuningSettingsOpen&&<div className="drawer-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)setTuningSettingsOpen(false)}}><aside className="tuning-drawer"><div className="drawer-header"><div><small>ROUTING SETTINGS</small><h2>调优配置</h2></div><button className="icon-button" title="关闭配置" onClick={()=>setTuningSettingsOpen(false)}><X size={18}/></button></div><div className="drawer-content">
            <form className="panel drawer-config-panel" onSubmit={saveAi}><div className="panel-heading"><div><h2>AI 分析模型</h2><p>用于分析近期指标并生成权重建议</p></div><Badge tone={aiForm.enabled?'green':'amber'}>{aiForm.enabled?'已启用':'已停用'}</Badge></div><div className="drawer-form-grid"><label>协议<select value={aiForm.provider} onChange={e=>setAiForm({...aiForm,provider:e.target.value,base_url:e.target.value==='anthropic'?'https://api.anthropic.com':'https://api.openai.com/v1'})}><option value="openai">OpenAI 兼容</option><option value="anthropic">Anthropic</option></select></label><label>分析模型<input value={aiForm.model} onChange={e=>setAiForm({...aiForm,model:e.target.value})} placeholder="例如 gpt-4.1-mini"/></label><label className="drawer-wide">API Base URL<input value={aiForm.base_url} onChange={e=>setAiForm({...aiForm,base_url:e.target.value})}/></label><label className="drawer-wide">API Token<input type="password" value={aiForm.api_key} onChange={e=>setAiForm({...aiForm,api_key:e.target.value})} placeholder={aiForm.key_saved?'已保存，留空保持不变':'用于 AI 分析的 Token'}/></label></div><div className="drawer-form-foot"><span><LockKeyhole size={13}/>Token 使用 Windows DPAPI 加密保存</span><button className="button primary small" disabled={busy}>保存 AI 配置</button></div></form>
            <form className="panel drawer-config-panel" onSubmit={saveRules}><div className="panel-heading"><div><h2>规则路由</h2><p>失败冷却与自动权重范围</p></div><Badge tone={ruleForm.enabled?'green':'neutral'}>{ruleForm.enabled?'已启用':'已停用'}</Badge></div><div className="drawer-form-grid"><label>连续失败阈值<input type="number" min="1" max="10" value={ruleForm.failure_threshold} onChange={e=>setRuleForm({...ruleForm,failure_threshold:+e.target.value})}/><small>达到阈值后进入冷却</small></label><label>冷却时长（秒）<input type="number" min="10" max="3600" value={ruleForm.cooldown_seconds} onChange={e=>setRuleForm({...ruleForm,cooldown_seconds:+e.target.value})}/><small>429 后暂按默认冷却时间</small></label><label>自动权重下限<input type="number" min="0.1" max="1" step="0.05" value={ruleForm.min_auto_factor} onChange={e=>setRuleForm({...ruleForm,min_auto_factor:+e.target.value})}/></label><label>自动权重上限<input type="number" min="1" max="3" step="0.05" value={ruleForm.max_auto_factor} onChange={e=>setRuleForm({...ruleForm,max_auto_factor:+e.target.value})}/></label></div><div className="drawer-form-foot"><span><ShieldCheck size={13}/>手动锁定权重优先于自动调权</span><button className="button primary small">保存规则</button></div></form>
          </div></aside></div>}
          {historyDrawer&&<div className="drawer-backdrop history-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)setHistoryDrawer(null)}}><aside className="tuning-drawer history-drawer"><div className="drawer-header"><div><small>HISTORY</small><h2>{historyDrawer==='weights'?'权重变更历史':'分析与建议审计'}</h2></div><button className="icon-button" title="关闭历史" onClick={()=>setHistoryDrawer(null)}><X size={18}/></button></div><div className="history-drawer-content">{historyDrawer==='weights'?historyData.weights.items.map(w=><article className="history-item" key={w.id}><div className="history-item-head"><div className="audit-icon"><Gauge size={15}/></div><div className="history-item-title"><b>{w.name||'已删除部署'} · {w.source==='ai'?'AI 调整':'规则调权'}</b><small>{fmtTime(w.created_at)} · {w.alias||w.deployment_id}</small></div><Badge tone={w.after_weight>=w.before_weight?'green':'amber'}>{w.source==='ai'?'AI':'规则'}</Badge></div><div className="history-weight-value">{Number(w.before_weight).toFixed(2)} <span>→</span> {Number(w.after_weight).toFixed(2)}</div><p>{w.reason}</p></article>):historyData.audits.items.map(a=><article className="history-item" key={a.id}><div className="history-item-head"><div className="audit-icon"><FileText size={15}/></div><div className="history-item-title"><b>{a.kind==='tune'?'AI 权重调整':'综合分析报告'}</b><small>{fmtTime(a.created_at)} · {a.kind==='tune'?`${a.changes?.length||0} 项变更`:`样本 ${a.report?.metrics?.sampled_events??a.report?.sampled_events??0} 条请求`}</small></div><Badge tone={a.status==='applied'||a.status==='complete'?'green':a.status==='rejected'||a.status==='failed'?'red':'amber'}>{a.status}</Badge><button className="text-button" onClick={()=>setExpandedHistoryId(expandedHistoryId===a.id?null:a.id)}>{expandedHistoryId===a.id?'收起':'查看详情'}</button></div><p className="history-summary">{a.report?.analysis_error||a.report?.summary||a.report?.error||'暂无摘要'}</p>{expandedHistoryId===a.id&&<pre className="history-json">{JSON.stringify({report:a.report,changes:a.changes},null,2)}</pre>}</article>)}{historyLoading&&<div className="history-empty">正在加载历史记录…</div>}{!historyLoading&&!historyData[historyDrawer].items.length&&<div className="history-empty">暂无历史记录。</div>}{historyData[historyDrawer].items.length<historyData[historyDrawer].total&&<button className="button secondary history-load-more" disabled={historyLoading} onClick={loadMoreHistory}>{historyLoading?'正在加载…':'加载更早记录'}</button>}</div><div className="history-footer">共 {historyData[historyDrawer].total} 条记录</div></aside></div>}
        </>}        {tab==='settings' && <><div className="settings-subnav"><button className={settingsSubtab==='general'?'active':''} onClick={()=>setSettingsSubtab('general')}>系统偏好</button><button className={settingsSubtab==='providers'?'active':''} onClick={()=>setSettingsSubtab('providers')}>厂商预设</button></div>{settingsSubtab==='providers'?<ProviderPresets initial={settings?.provider_presets||{}} onSave={saveProviderPresets}/>:<><div className="page-heading"><div><div className="eyebrow">PREFERENCES</div><h1>系统设置</h1><p>查看本地服务接入信息与数据保护配置。</p></div><Badge tone="green" dot>仅本机监听</Badge></div><div className="settings-grid"><div className="panel settings-card"><div className="settings-title"><div className="settings-icon"><Radio size={17}/></div><div><b>本地网关</b><small>客户端连接本地服务使用</small></div></div><label>Base URL</label><div className="copy-field"><code>{bootstrap?.base_url||'http://127.0.0.1:8787/v1'}</code><button onClick={()=>copy(bootstrap?.base_url||'http://127.0.0.1:8787/v1')}><Copy size={14}/></button></div><label>本地 API Key</label><div className="copy-field"><code>{showKey?bootstrap?.client_key:'••••••••••••••••••••••••••••'}</code><button onClick={()=>setShowKey(!showKey)}>{showKey?'隐藏':'显示'}</button></div><p className="field-hint">客户端请求使用 Bearer Token。初次启动时自动生成，保存在本地数据目录。</p></div><div className="panel settings-card"><div className="settings-title"><div className="settings-icon purple"><LockKeyhole size={17}/></div><div><b>数据与隐私</b><small>本地数据库及日志保护</small></div></div><div className="setting-line"><span>数据库</span><Badge>SQLite</Badge></div><div className="setting-line"><span>请求正文记录</span><Badge tone="green">关闭</Badge></div><div className="setting-line"><span>上游 Token 日志</span><Badge tone="green">脱敏</Badge></div><div className="setting-line"><span>Windows Token 加密</span><Badge tone="green">DPAPI</Badge></div><div className="setting-line"><span>数据目录</span><code>%USERPROFILE%\.local-model-router</code></div><p className="field-hint">API Token 使用当前 Windows 用户的 DPAPI 加密；请求正文默认不写入日志。</p></div></div><div className="panel protocol-panel"><div className="panel-heading"><div><h2>协议能力</h2><p>当前初版实现范围</p></div><Badge tone="blue">v0.1.0</Badge></div><div className="protocol-row"><div className="protocol-logo openai">O</div><div><b>OpenAI Chat Completions</b><small>/v1/chat/completions · /v1/models</small></div><Badge tone="green" dot>可用</Badge></div><div className="protocol-row"><div className="protocol-logo anthropic">A</div><div><b>Anthropic Messages</b><small>/v1/messages · 同协议流式透传与非流式适配</small></div><Badge tone="amber" dot>基础支持</Badge></div><div className="notice"><AlertTriangle size={15}/>跨协议流式转换、Responses API 与完整工具调用映射尚未纳入初版。</div></div></>}</>}
      </div>
    </main>
    {selectedModel&&<div className="drawer-backdrop model-detail-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)setSelectedModel(null)}}><aside className="tuning-drawer model-detail-drawer" role="dialog" aria-modal="true" aria-label={`${selectedModel.name} 模型详情`}><div className="drawer-header"><div><small>MODEL DEPLOYMENT</small><h2>{selectedModel.name}</h2></div><button className="icon-button" title="关闭详情" onClick={()=>setSelectedModel(null)}><X size={18}/></button></div><div className="model-detail-intro"><div className={`provider-avatar ${providerColor(selectedModel.provider)}`}>{initials(selectedModel.name)}</div><div><b>{selectedModel.alias}</b><small>{selectedModel.provider==='anthropic'?'Anthropic':'OpenAI'} 兼容格式 · {selectedModel.upstream_model}</small></div><button type="button" role="switch" aria-checked={selectedModel.enabled} aria-label={selectedModel.enabled?'停用模型':'启用模型'} className={`model-enabled-switch ${selectedModel.enabled?'is-enabled':''}`} onClick={()=>toggleDeployment(selectedModel)}><span/>{selectedModel.enabled?'已启用':'已停用'}</button></div><nav className="event-detail-tabs model-detail-tabs">{[['info','基础信息'],['config','配置'],['guide','接入教程']].map(([id,label])=><button key={id} className={modelDetailTab===id?'active':''} onClick={()=>setModelDetailTab(id)}>{label}</button>)}</nav><div className="event-drawer-content model-detail-content">{modelDetailTab==='info'&&<><h3>模型信息</h3><div className="event-info-list">{[['部署名称',selectedModel.name],['逻辑模型',selectedModel.alias],['上游模型',selectedModel.upstream_model],['状态',selectedModel.health|| (selectedModel.enabled?'运行正常':'已停用')],['生效权重',Number(selectedModel.effective_weight||0).toFixed(2)],['速率限制',selectedModel.rpm?`${selectedModel.rpm} RPM`:'未设置'],['凭据数量',`${selectedModel.key_count||0} 个`]].map(([label,value])=><div key={label}><span>{label}</span><code>{value??'—'}</code></div>)}</div><p className="field-hint">凭据内容不会在详情中显示。</p></>}{modelDetailTab==='config'&&<><h3>当前配置</h3><div className="event-info-list">{[['上游地址',selectedModel.base_url],['代理',selectedModel.proxy_url|| (selectedModel.use_system_proxy?'使用系统代理':'直连')],['超时时间',`${selectedModel.timeout_seconds??90} 秒`],['最大输入 Token',selectedModel.max_input_tokens||'未设置'],['最大输出 Token',selectedModel.max_output_tokens||'未设置'],['思考模式',selectedModel.thinking_mode?'开启':'关闭'],['权重锁定',selectedModel.weight_locked?'已锁定':'自动调节'],['备注',selectedModel.note||'—']].map(([label,value])=><div key={label}><span>{label}</span><code>{value??'—'}</code></div>)}</div><button className="button secondary model-edit-button" onClick={()=>{setSelectedModel(null);openEdit(selectedModel)}}><Settings2 size={14}/>编辑配置</button></>}{modelDetailTab==='guide'&&<><h3>客户端接入</h3><p className="model-guide-copy">将客户端的 API 地址指向本地模型路由器，并使用逻辑模型名称。</p><div className="event-info-list"><div><span>API 地址</span><code>http://127.0.0.1:8787/v1</code></div><div><span>模型名称</span><code>{selectedModel.alias}</code></div><div><span>API Key</span><code>使用本地路由器配置的客户端密钥</code></div></div><h3 className="model-guide-subtitle">OpenAI 兼容示例</h3><div className="model-code-wrap"><button className="model-code-copy" onClick={()=>copy(['from openai import OpenAI','','client = OpenAI(','    base_url="http://127.0.0.1:8787/v1",','    api_key="YOUR_LOCAL_API_KEY",',')','','response = client.chat.completions.create(','    model="'+selectedModel.alias+'",','    messages=[{"role": "user", "content": "Hello"}],',')'].join('\n'))}><Copy size={13}/>复制</button><pre className="model-guide-code">{'from openai import OpenAI\n\nclient = OpenAI(\n    base_url="http://127.0.0.1:8787/v1",\n    api_key="YOUR_LOCAL_API_KEY",\n)\n\nresponse = client.chat.completions.create(\n    model="'+selectedModel.alias+'",\n    messages=[{"role": "user", "content": "Hello"}],\n)'}</pre></div><h3 className="model-guide-subtitle">cURL 示例</h3><div className="model-code-wrap"><button className="model-code-copy" onClick={()=>copy('curl http://127.0.0.1:8787/v1/chat/completions -H "Content-Type: application/json" -H "Authorization: Bearer YOUR_LOCAL_API_KEY" -d \'{"model":"'+selectedModel.alias+'","messages":[{"role":"user","content":"Hello"}]}\'')}><Copy size={13}/>复制</button><pre className="model-guide-code">{'curl http://127.0.0.1:8787/v1/chat/completions \\\n  -H "Content-Type: application/json" \\\n  -H "Authorization: Bearer YOUR_LOCAL_API_KEY" \\\n  -d \'{"model":"'+selectedModel.alias+'","messages":[{"role":"user","content":"Hello"}]}\''}</pre></div><p className="field-hint">请求会通过此逻辑模型自动路由到已配置的供应商部署。</p></>}</div></aside></div>}
    {modal&&<DeploymentDialog editing={editing} form={form} setForm={setForm} emptyForm={emptyForm} keyText={keyText} setKeyText={setKeyText} availableModels={availableModels} setAvailableModels={setAvailableModels} deps={deps} providerPresets={settings?.provider_presets} busy={busy} testingConnection={testingConnection} fetchingModels={fetchingModels} onSave={saveDeployment} onTest={testDeployment} onFetch={fetchModels} onClose={()=>setModal(false)}/> }
    {selectedEvent&&<div className="event-drawer-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)setSelectedEvent(null)}}><aside className="event-drawer" role="dialog" aria-modal="true" aria-label="请求路由详情"><div className="event-drawer-header"><div><div className="eyebrow">REQUEST TRACE</div><h2>请求路由详情</h2></div><button type="button" className="icon-button" onClick={()=>setSelectedEvent(null)} aria-label="关闭"><X size={18}/></button></div><div className="event-drawer-summary"><span className={`badge ${selectedEvent.status==='success'?'green':'red'}`}><i/>{selectedEvent.status==='success'?'成功':'失败'}</span><span className="badge blue">{selectedEvent.protocol||'未知协议'}</span><code>{selectedEvent.request_id}</code><button className="icon-button" aria-label="复制请求 ID" onClick={()=>copy(selectedEvent.request_id)}><Copy size={14}/></button></div><nav className="event-detail-tabs" aria-label="请求详情分类">{[['overview','概览'],['attempts',`路由尝试 (${selectedEvent.attempts?.length||0})`],['error','错误信息'],['raw','原始记录']].map(([id,label])=><button key={id} className={eventDetailTab===id?'active':''} onClick={()=>setEventDetailTab(id)}>{label}</button>)}</nav><div className="event-drawer-content">{eventDetailTab==='overview'&&<><div className="event-metrics"><div><small>耗时</small><b>{formatDuration(selectedEvent.latency_ms)}</b></div><div><small>状态码</small><b>{selectedEvent.status_code??'—'}</b></div><div><small>Token 总量</small><TokenUsage event={selectedEvent}/></div></div><div className="event-info-list">{[['请求 ID',selectedEvent.request_id],['逻辑模型',selectedEvent.alias],['部署',selectedEvent.deployment_name],['供应商',selectedEvent.supplier_name],['协议',selectedEvent.protocol],['发生时间',fmtTime(selectedEvent.created_at)],['结果',selectedEvent.status]].map(([label,value])=><div key={label}><span>{label}</span><code>{value??'—'}</code></div>)}</div><p className="field-hint">仅展示可用的脱敏路由记录，不包含请求正文或 API Token。</p></>}{eventDetailTab==='attempts'&&<>{selectedEvent.attempts?.length?selectedEvent.attempts.map((attempt,index)=><section className="attempt-card" key={index}><div><b>尝试 {index+1}</b><span className={`badge ${attempt.status==='error'?'red':'green'}`}>{attempt.status}</span></div><div className="event-info-list">{[['部署',attempt.deployment],['供应商',attempt.supplier_name],['凭据序号',attempt.credential],['状态码',attempt.status],['错误类型',attempt.error_kind]].filter(([,v])=>v!=null).map(([label,value])=><div key={label}><span>{label}</span><code>{String(value)}</code></div>)}</div></section>):<div className="event-empty">没有记录路由尝试信息</div>}</>}{eventDetailTab==='error'&&<>{selectedEvent.error_message||selectedEvent.error_kind?<><div className="event-tab-heading"><div className="event-error-kind">{selectedEvent.error_kind||'错误详情'}</div><button className="button secondary small" onClick={()=>copy(selectedEvent.error_message||selectedEvent.error_kind)}><Copy size={14}/>复制错误信息</button></div><pre className="event-error-message">{selectedEvent.error_message||'无错误摘要'}</pre></>:<div className="event-empty">此请求没有错误信息</div>}</>}{eventDetailTab==='raw'&&<><div className="event-tab-heading"><span>完整事件数据</span><button className="button secondary small" onClick={()=>copy(JSON.stringify(selectedEvent,null,2))}><Copy size={14}/>复制原始记录</button></div><pre className="trace-json event-raw-json">{JSON.stringify(selectedEvent,null,2)}</pre></>}</div><div className="event-drawer-footer"><span className="field-hint">不包含请求正文或 API Token</span><button className="button primary" onClick={()=>copy(selectedEvent.request_id)}><Copy size={14}/>复制请求 ID</button></div></aside></div>}
    {toast&&<div className="toast"><Check size={16}/>{toast}</div>}
  </div>
}

function ModelRow({dep:d,onSelect,onEdit,onDelete,expanded=false}) { const health=d.health==='cooldown'?'冷却中':d.health==='degraded'?'表现波动':d.health==='no_credentials'?'缺少 Token':d.enabled?'运行正常':'已停用'; return <tr onClick={onSelect} className={onSelect?'clickable-row':''}><td><div className="model-cell"><div className={`provider-avatar ${providerColor(d.provider)}`}>{initials(d.name)}</div><div><b>{d.name}</b><small>{d.upstream_model}</small></div></div></td><td><code>{d.alias}</code></td>{expanded&&<td><Badge tone={providerColor(d.provider)}>{d.provider==='anthropic'?'Anthropic':'OpenAI'}</Badge></td>}<td><Badge tone={d.health==='cooldown'?'amber':d.health==='degraded'||d.health==='no_credentials'?'red':d.enabled?'green':'neutral'} dot>{health}</Badge></td><td><div className="weight-cell"><b>{Number(d.effective_weight||0).toFixed(2)}</b>{d.weight_locked?<LockKeyhole size={12}/>:<span>自动</span>}</div></td><td><span className="key-count"><KeyRound size={13}/>{d.key_count}</span></td><td>{d.rpm||'—'}</td>{expanded&&<td>{d.proxy_url?<Badge tone="blue">自定义</Badge>:d.use_system_proxy?<Badge>系统</Badge>:<Badge>直连</Badge>}</td>}<td><div className="row-actions"><button title="编辑" onClick={e=>{e.stopPropagation();onEdit()}}><Settings2 size={15}/></button><button title="删除" onClick={e=>{e.stopPropagation();onDelete()}}><Trash2 size={15}/></button></div></td></tr> }
function EventRow({event:e,fmtTime}) {return <div className="event-row"><div className={`event-status ${e.status==='success'?'ok':'fail'}`}>{e.status==='success'?<Check size={13}/>:<X size={13}/>}</div><div className="event-main"><b>{e.alias||'未匹配模型'}</b><small>{e.deployment_name||e.error_message||'路由请求'}</small></div><Badge>{e.protocol==='anthropic'?'ANTHROPIC':'OPENAI'}</Badge><span className="event-time">{formatDuration(e.latency_ms)} <small>{fmtTime(e.created_at)}</small></span></div>}
function Empty({title,body,action}){return <div className="empty-state"><div className="empty-icon"><Cpu size={21}/></div><b>{title}</b><p>{body}</p>{action&&<button className="button primary small" onClick={action}><Plus size={14}/>添加模型</button>}</div>}

createRoot(document.getElementById('root')).render(<App/>)
